import{_ as t,o as a,c as i,a6 as s}from"./chunks/framework.CCKCzdWs.js";const n="/screenshots/setup-ladder-declined-wide.png",u=JSON.parse('{"title":"Choose what you use","description":"Pick the capabilities your instance and each project use from Settings → Capabilities, and decline the rest so the dashboard stops showing them.","frontmatter":{"title":"Choose what you use","description":"Pick the capabilities your instance and each project use from Settings → Capabilities, and decline the rest so the dashboard stops showing them.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/operate/capabilities.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/operate/capabilities.html"}],["meta",{"property":"og:title","content":"Choose what you use | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Pick the capabilities your instance and each project use from Settings → Capabilities, and decline the rest so the dashboard stops showing them."}]]},"headers":[],"relativePath":"operate/capabilities.md","filePath":"operate/capabilities.md","lastUpdated":1795263615000}'),o={name:"operate/capabilities.md"};function r(c,e,l,h,d,p){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="choose-what-you-use" tabindex="-1">Choose what you use <a class="header-anchor" href="#choose-what-you-use" aria-label="Permalink to &quot;Choose what you use&quot;">​</a></h1><p><strong>Settings → Capabilities</strong> (<code>/settings/capabilities</code>, administrators only) is where an instance says what else it does once results arrive. It opens on one coarse question, <em>What do you want Piwi for?</em>, with <strong>See why tests fail</strong> always on and three opt-out groups: <strong>Triage as a team</strong> (notifications, <a href="/features/flaky-tests.html#quarantine-with-a-way-out">quarantine</a>, pull-request feedback, issue tracking), <strong>Fix faster</strong> (locator healing, auto-heal), and <strong>Let agents in</strong> (AI diagnosis, the assistant). Below it, a ladder lists every optional capability grouped by state: <strong>Active</strong> (evidence has arrived), <strong>Available</strong> (configured but not used yet), <strong>Not set up</strong>, and a folded <strong>Declined</strong> group. The page ends with <strong>Off until turned on</strong>: <a href="/features/run-on-my-machine.html">Run on my machine</a> and <a href="/features/reuse-forecast.html">Pass reuse</a> stay off until an administrator turns them on.</p><h2 id="declining-a-capability" tabindex="-1">Declining a capability <a class="header-anchor" href="#declining-a-capability" aria-label="Permalink to &quot;Declining a capability&quot;">​</a></h2><p>Not every team uses every capability. Any optional one can be <strong>declined</strong> so the dashboard stops showing it everywhere: the evidence tabs, empty panels, settings page, sidebar entry, project actions and MCP tools it owns all go, rather than lingering half-visible. Decline instance-wide from the ladder (<em>Not for this instance</em>) or the presets, or per project from the <strong>Capabilities</strong> section of the project&#39;s <strong>Settings</strong> tab and the places the capability appears (for example the execution page&#39;s evidence footer, <em>Not for this project</em>). A project override can also <strong>enable</strong> a capability the instance declined.</p><p>Declining instance-wide is for administrators, and per project for the project&#39;s <a href="./project-access.html#project-roles">Project admin</a> role. It is never final: each declined capability keeps a <em>Reconsider</em> link on the ladder that clears the decision, and because data always wins, a declined capability that starts receiving data reads as active again with the stored decision shown next to it. <a href="#why-a-card-is-empty">Why a card is empty</a> says how this reads on the execution page.</p><figure><img src="'+n+'" alt="The Capabilities settings page&#39;s list of what is switched on, Notifications among the active capabilities, marked declined with a Reconsider link beside its docs link"><figcaption>A declined capability that still receives data reads as active, its decision and Reconsider link beside it.</figcaption></figure><h2 id="why-a-card-is-empty" tabindex="-1">Why a card is empty <a class="header-anchor" href="#why-a-card-is-empty" aria-label="Permalink to &quot;Why a card is empty&quot;">​</a></h2><p>On the <a href="/features/evidence.html">execution page</a>, a tab that needs the capture fixtures appears only when it holds data or the fixtures ran and found nothing; otherwise one footer line names the missing tabs. An empty card says which case applies: <strong>captured, nothing happened</strong>, <strong>not applicable</strong> (backend logs need a <a href="/guide/backend-logs.html">backend integration</a>), or <strong>declined</strong> for this project (<a href="#declining-a-capability">Declining a capability</a>). The AI diagnosis&#39;s <strong>Data coverage</strong> block uses the same words.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/getting-started.html">Getting started</a>: connect a first suite</li><li><a href="/reference/features.html">All features</a>: every capability and what it needs</li><li><a href="./integrations.html">Jira Cloud</a> and <a href="./zephyr-scale.html">Zephyr Scale Cloud</a>: connect the issue tracker and the test management tool some capabilities use</li></ul>',10)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
